NAME = 'CzeBKR: Czech Bible Kralicka'
BOOK = 'Mark'

CHAPTERS = {
    1: {
        1: 'Počátek evangelium Ježíše Krista, Syna Božího;',
        2: 'Jakož psáno jest v prorocích: Aj, já posílám anděla svého před tváří tvou, kterýž připraví cestu tvou před tebou.',
        3: 'Hlas volajícího na poušti: Připravujte cestu Páně, přímé čiňte stezky jeho.',
        4: 'Křtil Jan na poušti, a kázal křest pokání na odpuštění hříchů.',
        5: 'I vycházela k němu všecka krajina Judská i Jeruzalémští, a křtěni byli od něho všickni v Jordáně řece, vyznávajíce hříchy své.',
        6: 'Byl pak Jan odín srstmi velbloudovými, a pás kožený na bedrách jeho, a jídal kobylky a med lesní.',
        7: 'A kázal, řka: Jde za mnou silnější nežli já, kterémuž nejsem hoden, sehna se, rozvázati řeménka u obuvi jeho.',
        8: 'Já zajisté křtil jsem vás vodou, ale onť vás křtíti bude Duchem svatým.',
        9: 'I stalo se v těch dnech, přišel Ježíš z Nazarétu Galilejského, a pokřtěn jest od Jana v Jordáně.',
        10: 'A hned vystoupiv z vody, uzřel nebesa otevřená a Ducha jako holubici sstupujícího na něj.',
        11: 'A hlas stal se s nebe: Ty jsi ten můj milý Syn, v němž mi se dobře zalíbilo.',
        12: 'A i hned ho Duch vypudil na poušť.',
        13: 'I byl tam na poušti čtyřidceti dnů, a pokoušín byl od satana; a byl s zvěří, a andělé přisluhovali jemu.',
        14: 'Když pak byl vsazen Jan, přišel Ježíš do Galilee, káže evangelium království Božího,',
        15: 'A pravě: Že se naplnil čas, a přiblížilo se království Boží. Čiňte pokání, a věřte evangelium.',
        16: 'A chodě podlé moře Galilejského, uzřel Šimona a Ondřeje bratra jeho, ani pouštějí síti do moře, (nebo rybáři byli.)',
        17: 'I řekl jim Ježíš: Poďte za mnou, a učiním vás rybáře lidí.',
        18: 'A hned opustivše síti své, šli za ním.',
        19: 'A poodšed odtud maličko, uzřel Jakuba syna Zebedeova, a Jana bratra jeho, ani na lodí tvrdí síti.',
        20: 'A hned povolal jich. A oni opustivše otce svého Zebedea na lodí s pacholky, šli za ním.',
        21: 'I vešli do Kafarnaum. A hned v sobotu šed do školy, učil.',
        22: 'I divili se náramně učení jeho; nebo učil je, jako moc maje, a ne jako zákonníci.',
        23: 'I byl v škole jejich člověk, maje ducha nečistého. Kterýž zvolal,',
        24: 'Řka: Ach, což jest tobě do nás, Ježíši Nazaretský? Přišel jsi zatratiti nás. Znám tě, kdo jsi, že ten Svatý Boží.',
        25: 'I přimluvil mu Ježíš, řka: Umlkniž a vyjdi z něho.',
        26: 'I polomcovav jím duch nečistý a křiče hlasem velikým, vyšel z něho.',
        27: 'I lekli se všickni, tak že se tázali mezi sebou, řkouce: I co jest toto? Jakéž toto nové učení, že mocně i těm duchům nečistým rozkazuje, a poslouchají ho?',
        28: 'I roznesla se pověst o něm hned po vší krajině Galilejské.',
        29: 'A hned vyšedše ze školy, přišli do domu Šimonova a Ondřejova s Jakubem a s Janem.',
        30: 'Šimonova pak svegruše ležela, majíc zimnici. A hned jemu pověděli o ní.',
        31: 'A přistoupiv, pozdvihl jí, ujav ji za ruku její, a hned přestala jí zimnice. I posluhovala jim.',
        32: 'Večer pak při západu slunce, nosili k němu všecky nemocné i ďábelníky.',
        33: 'A bylo se všecko město zběhlo ke dveřím.',
        34: 'I uzdravoval mnohé ztrápené rozličnými neduhy, a ďábelství mnohá vymítal, a nedopouštěl mluviti ďáblům; nebo znali ho.',
        35: 'A přede dnem velmi ráno vstav, vyšel a odšel na pusté místo, a tam se modlil.',
        36: 'I šli za ním Šimon i ti, kteříž s ním byli.',
        37: 'A nalezše jej, řekli jemu: Všickni tě hledají.',
        38: 'I dí jim: Poďmež do okolních městeček, abych i tam kázal. Nebo na to jsem přišel.',
        39: 'I kázal v školách jejich ve vší Galilei, a ďábelství vymítal.',
        40: 'Tedy přišel k němu malomocný, prose ho, a klekna před ním, řekl jemu: Chceš-li, můžeš mne očistiti.',
        41: 'Ježíš pak slitovav se, vztáhl ruku, dotekl se ho a řekl jemu: Chci, buď čist.',
        42: 'A když to řekl, hned odstoupilo od něho malomocenství, a očištěn jest.',
        43: 'I zapověděv mu přísně, hned ho odbyl,',
        44: 'A řekl mu: Viziž, abys žádnému nic nepravil. Ale jdi, ukaž se knězi, a obětuj za očištění své to, což přikázal Mojžíš, na svědectví proti nim.',
        45: 'On pak vyšed, počal vypravovati mnoho a ohlašovati tu věc, tak že již nemohl Ježíš do města zjevně vjíti, ale vně na místech pustých byl. I scházeli se k němu odevšad.',
    },
    2: {
        1: 'A opět všel do Kafarnaum po kolikas dnech. I uslyšáno jest, že by doma byl.',
        2: 'A hned sešlo se jich množství, tak že již nemohli se směstknati ani přede dveřmi. I mluvil jim slovo.',
        3: 'Tedy přišli k němu, nesouce šlakem poraženého, kterýž ode čtyř nesen byl.',
        4: 'A když k němu nemohli přistoupiti pro zástupy, loupali střechu, kdež byl, a probořivše ji, spustili po provazích dolů ložce, na němž ležel šlakem poražený.',
        5: 'A vida Ježíš víru jejich, dí šlakem poraženému: Synu, odpouštějí se tobě hříchové tvoji.',
        6: 'A byli tu někteří z zákonníků, sedíce a myslíce v srdcích svých:',
        7: 'Co tento tak mluví rouhavě? Kdo můž odpustiti hříchy, jediné sám Bůh?',
        8: 'I poznav Ježíš hned duchem svým, že by tak přemyšlovali sami v sobě, řekl jim: Proč o tom přemyšlujete v srdcích svých?',
        9: 'Co jest snáze, říci šlakem poraženému: Odpouštějí se tobě hříchové, čili říci: Vstaň, vezmi lože své a choď?',
        10: 'Ale abyste věděli, že Syn člověka má moc na zemi odpouštěti hříchy, dí šlakem poraženému:',
        11: 'Toběť pravím: Vstaň, a vezmi lože své, a jdi do domu svého.',
        12: 'I vstal hned, a vzav lože své přede všemi, odšel, tak že se děsili všickni, a chválili Boha, řkouce: Nikdy jsme toho neviděli.',
        13: 'I vyšel opět k moři, a všecken zástup přicházel k němu, i učil je.',
        14: 'A pomíjeje, uzřel Léví Alfeova, sedícího na cle. I dí jemu: Poď za mnou. A on vstav, šel za ním.',
        15: 'I stalo se, když seděl Ježíš za stolem v domě jeho, že i publikáni mnozí a hříšníci seděli spolu s Ježíšem a s učedlníky jeho; nebo mnoho jich bylo, a šlo za ním.',
        16: 'Zákonníci pak a farizeové viděvše, že jedl s publikány a s hříšníky, řekli učedlníkům jeho: Což to, že s publikány a hříšníky jí a pije?',
        17: 'To uslyšav Ježíš, dí jim: Nepotřebují zdraví lékaře, ale nemocní. Nepřišelť jsem volati spravedlivých, ale hříšných ku pokání.',
        18: 'Učedlníci pak Janovi a farizejští postívali se. I přišli a řekli jemu: Proč učedlníci Janovi a farizejští postí se, a tvoji učedlníci se nepostí?',
        19: 'I řekl jim Ježíš: Kterakž mohou synové ženichovi postiti se, když jest s nimi ženich? Dokudž mají s sebou ženicha, nemohouť se postiti.',
        20: 'Ale přijdouť dnové, když od nich odjat bude ženich, a tehdáž se budou postiti v těch dnech.',
        21: 'Ano žádný záplaty sukna nového nepřišívá k rouchu starému; jinak odtrhne ta záplata nová od starého, i bývá větší díra.',
        22: 'A žádný nevlévá vína nového do nádob starých; jinak rozpučí nové víno nádoby, a víno se vyleje, a nádoby se pokazí. Ale víno nové má lito býti do nádob nových.',
        23: 'I stalo se, že šel Ježíš v sobotu skrze obilí, i počali učedlníci jeho, cestou jdouce, vymínati klasy.',
        24: 'Tedy farizeové řekli jemu: Pohleď, coť dělají v sobotu, čehož nenáleží.',
        25: 'I řekl jim: Nikdy-liž jste nečtli, co učinil David, když nouze byla, a lačněl, on i ti, kteříž s ním byli?',
        26: 'Kterak všel do domu Božího za Abiatara nejvyššího kněze {biskupa}, a jedl chleby posvátné, (jichž neslušelo jísti než samým kněžím,) a dal i těm, kteříž s ním byli?',
        27: 'I pravil jim: Sobota pro člověka učiněna jest, a ne člověk pro sobotu.',
        28: 'Protož Syn člověka jest pánem také i soboty.',
    },
    3: {
        1: 'I všel opět do školy, a byl tu člověk, maje ruku uschlou.',
        2: 'I šetřili ho, uzdraví-li jej v sobotu, aby ho obžalovali.',
        3: 'I řekl tomu člověku, kterýž měl uschlou ruku: Povstaň u prostřed.',
        4: 'I dí jim: Sluší-li v sobotu dobře činiti, čili zle, život zachovati, čili zamordovati? Oni pak mlčeli.',
        5: 'A když pohleděl na ně vůkol s hněvem, zarmoutiv se nad tvrdostí srdce jejich, řekl člověku: Vztáhni tu ruku svou. I vztáhl, a učiněna jest ta ruka jeho zdravá jako druhá.',
        6: 'A vyšedše farizeové, hned s Herodiány drželi radu proti němu, kterak by ho zahubili.',
        7: 'Ježíš pak odšel s učedlníky svými k moři, a veliké množství od Galilee šlo za ním, i z Judstva,',
        8: 'I od Jeruzaléma, i od Idumee, i z Zajordání; i ti, kteříž byli okolo Týru a Sidonu, množství veliké, slyšíce, kteraké věci činí, přišli k němu.',
        9: 'I rozkázal učedlníkům svým, aby lodičku ustavičně nahotově měli pro zástup, aby ho netiskli.',
        10: 'Nebo mnohé uzdravoval, tak že naň padali, aby se ho dotýkali, kteřížkoli měli neduhy.',
        11: 'A duchové nečistí, jakž ho zazřeli, padali před ním a křičeli, řkouce: Ty jsi ten Syn Boží.',
        12: 'Ale on velmi jim přimlouval, aby ho nezjevovali.',
        13: 'I vstoupil na horu, a povolal k sobě těch, kterýchž se jemu vidělo; i přišli k němu.',
        14: 'I ustanovil jich dvanácte, aby s ním byli, a aby je poslal kázati,',
        15: 'A aby měli moc uzdravovati nemoci a vymítati ďábelství:',
        16: 'Šimona, jemuž dal jméno Petr,',
        17: 'A Jakuba Zebedeova, a Jana bratra Jakubova, (a dal jim jméno Boanerges, to jest synové hromovi,)',
        18: 'A Ondřeje, a Filipa, a Bartoloměje, a Matouše, a Tomáše, a Jakuba Alfeova, a Taddea, a Šimona Kananitského,',
        19: 'A Jidáše Iškariotského, kterýž i zradil jej. I šli s ním domů.',
        20: 'A opět sšel se zástup, tak že nemohli ani chleba pojísti.',
        21: 'A slyšavše o tom příbuzní jeho, přišli, aby jej vzali; nebo pravili, že by se smyslem pominul.',
        22: 'Zákonníci pak, kteříž byli přišli z Jeruzaléma, pravili, že Belzebuba má, a že v knížeti ďábelském vymítá ďábly.',
        23: 'A povolav jich, mluvil k nim v podobenstvích: Kterak může satan satana vymítati?',
        24: 'A jestliže království v sobě se rozdvojí, nemůže státi království to.',
        25: 'A rozdvojí-li se dům proti sobě, nebude moci dům ten státi.',
        26: 'Tak jestliže povstal satan sám proti sobě, a rozdvojen jest, nemůže státi, ale konec béře.',
        27: 'Žádný nemůže nádobí silného, vejda do domu jeho, rozebrati, leč by prvé silného toho svázal; a tehdyť dům jeho zloupí.',
        28: 'Amen pravím vám, že všickni hříchové odpuštěni budou synům lidským, i rouhání, jímž by se rouhali,',
        29: 'Ale kdo by se rouhal proti Duchu svatému, nemá odpuštění na věky, ale hoden jest věčného odsouzení.',
        30: 'Nebo pravili: Ducha nečistého má.',
        31: 'Tehdy přišli bratří a matka jeho, a stojíce vně, poslali k němu, aby ho vyvolali.',
        32: 'A seděl okolo něho zástup. I řekli jemu: Aj, matka tvá a bratří tvoji vně hledají tebe.',
        33: 'Ale on odpověděl jim, řka: Kdo jest matka má a bratří moji?',
        34: 'A obezřev učedlníky vůkol sebe sedící, řekl: Aj, matka má a bratří moji.',
        35: 'Nebo kdož by koli činil vůli Boží, ten jest bratr můj, i sestra má, i matka.',
    },
    4: {
        1: 'A opět počal učiti u moře. I shromáždil se k němu zástup mnohý, tak že vstoupiv na lodí, seděl na moři, a všecken zástup byl na zemi podlé moře.',
        2: 'I učil je mnohým věcem v podobenstvích, a pravil jim v učení svém:',
        3: 'Slyšte. Aj, vyšel rozsevač, aby rozsíval.',
        4: 'I stalo se v tom rozsívání, že jedno padlo podlé cesty, a přiletělo ptactvo nebeské, i zzobalo je.',
        5: 'A jiné padlo na místo skalnaté, kdež nemělo mnoho země, a hned vzešlo, proto že nemělo hlubokosti země.',
        6: 'A když vyšlo slunce, vyhořelo, a proto, že nemělo kořene, uschlo.',
        7: 'A jiné padlo mezi trní; i zrostlo trní, a udusilo je. I nevydalo užitku.',
        8: 'Jiné pak padlo v zemi dobrou, a dalo užitek zhůru vstupující a rostoucí; přineslo zajisté jedno třidcátý, a jiné šedesátý, a jiné pak stý.',
        9: 'I pravil jim: Kdo má uši k slyšení, slyš.',
        10: 'Když pak byl sám, tázali se ho ti, kteříž při něm byli, se dvanácti, na to podobenství.',
        11: 'I řekl jim: Vámť jest dáno, znáti tajemství království Božího, ale těm, kteříž jsou vně, v podobenství to všecko se děje,',
        12: 'Aby hledíce, hleděli, ale neuzřeli a slyšíce, slyšeli, ale nesrozuměli, aby se snad neobrátili, a byli by jim odpuštěni hříchové.',
        13: 'I dí jim: Neznáte podobenství tohoto? A kterakž pak všecka podobenství poznáte?',
        14: 'Rozsevač ten slovo rozsívá.',
        15: 'Tito pak jsou, ješto podlé cesty, jimž se rozsívá slovo, ale když oni slyší, i hned přichází satan, a vynímá slovo, kteréž vsáto jest v srdcích jejich.',
        16: 'A tak podobně ti, kteříž jako skalnatá země posáti jsou, kteříž jakž uslyší slovo, hned s radostí přijímají je.',
        17: 'Než nemají kořene v sobě, ale jsou časní; potom když vznikne ssoužení a protivenství pro slovo, hned se horší.',
        18: 'Tito pak jsou, kteříž mezi trní posáti jsou, ti jsou, kteříž slovo slyší,',
        19: 'Však pečování tohoto světa a oklamání zboží, a jiné žádosti přistupující, udušují slovo, tak že bez užitku bývá.',
        20: 'Tito pak jsou, kteříž v zemi dobrou símě přijali, kteříž slyší slovo, a přijímají, a užitek přinášejí, jiné třidcátý, a jiné šedesátý, a jiné stý.',
        21: 'Dále pravil jim: Zdali rozsvícena bývá svíce, aby postavena byla pod nádobu neb pod postel? Však aby na svícen vstavena byla.',
        22: 'Nebo nic není skrytého, co by nebylo zjeveno; aniž jest co tak ukrytého, aby na jevo nevyšlo.',
        23: 'Jestliže kdo má uši k slyšení, slyš.',
        24: 'I mluvil k nim: Vizte, co slyšíte. Kterou měrou budete měřiti, bude vám odměřeno, a přidáno bude vám poslouchajícím.',
        25: 'Nebo kdožť má, tomu bude dáno; a kdo nemá, i to, což má, bude od něho odjato.',
        26: 'I pravil: Tak jest království Boží, jako kdyby člověk uvrhl símě do země.',
        27: 'A spal by, a vstával by ve dne i v noci a semeno by vzešlo a zrostlo, jakž on neví.',
        28: 'Nebo sama od sebe země užitek plodí, nejprv bylinu, potom klas, potom plné obilé v klasu.',
        29: 'A když sezrá úroda, i hned přičiní srp; nebo nastala žeň.',
        30: 'I řekl: K čemu připodobníme království Boží? Aneb kterým podobenstvím je ukážeme?',
        31: 'Jest jako zrno horčičné, kteréž, když vsáto bývá do země, nejmenší jest ze všech semen, kteráž jsou na zemi.',
        32: 'Ale když vsáto bývá, roste, a bývá větší než všecky byliny, a činí ratolesti veliké, tak že pod stínem jeho mohou sobě ptáci nebeští hnízda dělati.',
        33: 'A takovými mnohými podobenstvími mluvil jim slovo, jakž mohli slyšeti.',
        34: 'Bez podobenství pak nemluvil jim, ale učedlníkům svým soukromí vykládal všecko.',
        35: 'I řekl jim v ten den, když již byl večer: Plavme se na druhou stranu.',
        36: 'A nechavše zástupu, pojali jej, tak jakž byl na lodičce. Ale i jiné lodičky byly s ním.',
        37: 'Tedy stala se bouře veliká od větru, až se vlny na lodí valily, tak že se již naplňovala lodí.',
        38: 'A on z zadu na lodí spal na podušce. I zbudili jej, a řekli jemu: Mistře, nedbáš, že hyneme?',
        39: 'I probudiv se, přimluvil větru, a řekl moři: Umlkni, a upokoj se. I přestal vítr, a stalo se utišení veliké.',
        40: 'I řekl jim: Proč se tak bojíte? Jakž to, že nemáte víry?',
        41: 'I báli se bázní velikou, a pravili jeden k druhému: I kdo jest medle tento, že i vítr i moře poslouchají jeho?',
    },
    5: {
        1: 'Tedy přeplavili se přes moře do krajiny Gadarenských.',
        2: 'A jakž vyšel z lodí, hned se s ním potkal člověk z hrobů, maje ducha nečistého.',
        3: 'Kterýž bydlil v hrobích, a aniž ho kdo mohl řetězy svázati,',
        4: 'Proto že často byv pouty a řetězy okován, polámal řetězy, a pouta roztrhal, a žádný nemohl ho skrotiti.',
        5: 'A vždycky ve dne i v noci na horách a v hrobích byl, křiče a tepa se kamením.',
        6: 'Uzřev pak Ježíše zdaleka, běžel a poklonil se jemu,',
        7: 'A křiče hlasem velikým, řekl: Co jest tobě do mne, Ježíši, Synu Boha nejvyššího? Zaklínám tě skrze Boha, abys mne netrápil.',
        8: '(Nebo pravil jemu: Vyjdiž, duchu nečistý, z člověka tohoto.)',
        9: 'I otázal se ho: Jakť říkají? A on odpovídaje, řekl: Množství jméno mé jest, nebo jest nás mnoho.',
        10: 'I prosil ho velmi, aby jich nevyháněl z té krajiny.',
        11: 'Bylo pak tu při horách stádo vepřů veliké pasoucích se.',
        12: 'I prosili ho všickni ti ďáblové, řkouce: Pusť nás do vepřů, ať do nich vejdeme.',
        13: 'I povolil jim hned Ježíš. A vyšedše duchové nečistí, vešli do těch vepřů. I běželo to stádo s vrchu dolů do moře, (a bylo jich ke dvěma tisícům,) i ztonuli v moři.',
        14: 'Ti pak, kteříž ty vepře pásli, utekli, a oznámili to v městě i ve vsech. I vyšli, aby viděli, co by to bylo, což se stalo.',
        15: 'I přišli k Ježíšovi, a uzřeli toho, kterýž býval trápen od ďábelství, an sedí, odín jsa, a maje zdravý rozum, toho, kterýž míval množství. I báli se.',
        16: 'A kteříž to viděli, vypravovali jim, kterak se stalo tomu, kterýž měl ďábelství i o vepřích.',
        17: 'Tedy počali ho prositi, aby odšel z krajin jejich.',
        18: 'A když vstoupil na lodí, prosil ho ten, kterýž trápen býval od ďábelství, aby s ním byl.',
        19: 'Ježíš pak nedopustil mu, ale řekl jemu: Jdi k svým do domu svého, a zvěstuj jim, kterak veliké věci učinil tobě Pán, a že slitoval se nad tebou.',
        20: 'I odšel, a počal ohlašovati v krajině Desíti měst, kterak veliké věci učinil mu Ježíš. I divili se všickni.',
        21: 'A když se přeplavil Ježíš na lodí zase na druhou stranu, sšel se k němu zástup mnohý. A byl u moře.',
        22: 'A aj, přišel jeden z knížat školy, jménem Jairus, a uzřev jej, padl k nohám jeho.',
        23: 'A velmi ho prosil, řka: Dcerka má skonává. Poď, vlož na ni ruce, aby uzdravena byla, a budeť živa.',
        24: 'I šel s ním, a zástup mnohý šel za ním, i tiskl jej.',
        25: '(Tedy žena jedna, kteráž tok krve měla dvanácte let,',
        26: 'A mnoho byla trápena od mnohých lékařů, a vynaložila všecken statek svůj, a nic jí bylo neprospělo, ale vždy se hůře měla,',
        27: 'Uslyšavši o Ježíšovi, přišla v zástupu po zadu, a dotkla se roucha jeho.',
        28: 'Nebo řekla byla: Dotknu-li se jen roucha jeho, uzdravena budu.',
        29: 'A hned přestal krvotok její, a pocítila na těle, že by uzdravena byla od neduhu svého.',
        30: 'A hned Ježíš poznav sám v sobě, že z něho moc vyšla, obrátiv se v zástupu, řekl: Kdo se dotekl roucha mého?',
        31: 'I řekli mu učedlníci jeho: Vidíš, že tě zástup tiskne, a pravíš: Kdo se mne dotekl?',
        32: 'I hleděl vůkol, aby ji uzřel, která to učinila.',
        33: 'Ta pak žena s bázní a s třesením, věduci, co se stalo při ní, přistoupila a padla před ním, a pověděla mu všecku pravdu.',
        34: 'On pak řekl jí: Dcero, víra tvá tě uzdravila, jdiž u pokoji, a buď zproštěna od trápení svého.)',
        35: 'A když on ještě mluvil, přišli z domu knížete školy, řkouce: Dcera tvá umřela, proč již zaměstknáváš Mistra?',
        36: 'Ježíš pak, hned jakž uslyšel to, což oni mluvili, řekl knížeti školy: Neboj se, toliko věř.',
        37: 'I nedal žádnému za sebou jíti, jediné Petrovi, Jakubovi a Janovi, bratru Jakubovu.',
        38: 'I přišel do domu knížete školy, a viděl tam hluk, ano plačí a kvílí velmi.',
        39: 'I všed tam, řekl jim: Co se bouříte a plačete? Neumřelať děvečka, ale spí.',
        40: 'I posmívali se jemu. On pak vyhnav všecky, pojal otce a matku děvečky, a ty, kteříž s ním byli, i všel tam, kdež děvečka ležela.',
        41: 'A vzav ruku děvečky, řekl jí: Talitha kumi. Což se vykládá: Děvečko, (toběť pravím,) vstaň.',
        42: 'A hned vstala děvečka, a chodila; nebo byla ve dvanácti letech. I zděsili se divením převelikým.',
        43: 'A přikázal jim pilně, aby žádný o tom nezvěděl. I rozkázal jí dáti jísti.',
    },
    6: {
        1: 'I vyšel odtud a přišel do vlasti své, a šli za ním učedlníci jeho.',
        2: 'A když bylo v sobotu, počal učiti v škole, a mnozí slyšíce, děsili se, řkouce: Odkud tento má tyto věci? A jaká jest to moudrost, kteráž jest dána jemu, že i takové moci dějí se skrze ruce jeho?',
        3: 'Zdaliž tento není ten tesař, syn Marie, bratr pak Jakubův a Jozesův a Judův a Šimonův? A zdaliž nejsou i sestry jeho zde u nás? I horšili se na něm.',
        4: 'I řekl jim Ježíš: Není prorok beze cti, jediné v vlasti své a v rodině své a v domě svém.',
        5: 'I nemohl tu divu žádného učiniti, jediné málo nemocných, vzkládaje na ně ruce, uzdravil.',
        6: 'I podivil se jejich nevěře, a obcházel vůkol po městečkách, uče.',
        7: 'A svolav k sobě těch dvanácte, počal je posílati po dvou a dvou, a dal jim moc nad duchy nečistými.',
        8: 'A přikázal jim, aby ničeho nebrali na cestu, jediné toliko hůl, ani mošny, ani chleba, ani do opasku peněz,',
        9: 'Ale aby obuté měli nohy v střevíce, a neobláčeli dvou sukní.',
        10: 'A pravil jim: Kdežkoli vešli byste do domu, tu ostaňte, dokudž nevyšli byste odtud.',
        11: 'A kdož by koli vás nepřijali, ani vás neposlouchali, vyjdouce odtud, vyrazte prach z noh svých na svědectví jim. Amen pravím vám: Lehčeji bude Sodomským a Gomorským v den soudný než městu tomu.',
        12: 'Tedy vyšedše, kázali, aby pokání činili.',
        13: 'A ďábelství mnohá vymítali, a mazali olejem mnohé nemocné, i uzdravovali.',
        14: 'A uslyšev o tom Heródes král, (nebo zjevné učiněno bylo jméno jeho,) pravil, že Jan Křtitel vstal z mrtvých, a protož divové dějí se skrze něho.',
        15: 'Jiní pak pravili, že jest Eliáš; a jiní pravili, že jest prorok, aneb jako jeden z těch proroků.',
        16: 'To uslyšev Heródes, řekl: Totoť jest ten Jan, kteréhož jsem já sťal. Ontě z mrtvých vstal.',
        17: 'Ten zajisté Heródes poslav, jal Jana, a vsadil jej do žaláře pro Herodiadu manželku Filipa bratra svého, že ji byl za manželku pojal.',
        18: 'Nebo pravil Jan Heródesovi: Neslušíť tobě míti manželky bratra svého.',
        19: 'Herodias pak lest skládala proti němu, a chtěla jej o hrdlo připraviti, ale nemohla.',
        20: 'Nebo Heródes ostýchal se Jana, věda jej býti muže spravedlivého a svatého. I šetřil ho, a slýchaje jej, mnoho i činil, a rád ho poslouchal.',
        21: 'Když pak přišel den příhodný, v němž Heródes, pamatuje den svého narození, učinil večeři knížatům svým a hejtmanům a předním mužům z Galilee,',
        22: 'A když dcera té Herodiady tam vešla a tancovala, a zalíbila se Heródesovi i spoluhodovníkům, řekl král děvečce: Pros mne, zač chceš, a dámť.',
        23: 'I přisáhl jí: Že začkoli prositi budeš, dám tobě, by pak bylo až do polovice království mého.',
        24: 'Ona pak vyšedši, řekla mateři své: Zač budu prositi? A ona řekla: Za hlavu Jana Křtitele.',
        25: 'A všedši hned s chvátáním k králi, prosila, řkuci: Chci, abys mi dal hned na mise hlavu Jana Křtitele.',
        26: 'Král pak zarmoutiv se velmi, pro přísahu a pro spoluhodovníky nechtěl jí oslyšeti.',
        27: 'Protož král ten poslav hned kata, rozkázal přinesti hlavu Janovu.',
        28: 'A on odšed, sťal jej v žaláři, a přinesl hlavu jeho na mise, a dal ji děvečce, a děvečka dala ji mateři své.',
        29: 'Tedy uslyševše to učedlníci jeho, přišli, a vzali tělo jeho, a pochovali je v hrobě.',
        30: 'Tehdy sšedše se apoštolé k Ježíšovi, zvěstovali jemu všecko, i to, co činili, i co učili.',
        31: 'I řekl jim: Poďte vy sami obzvláštně na pusté místo, a odpočiňte maličko. Nebo bylo množství těch, kteříž přicházeli a odcházeli, tak že ani k jídlu chvíle neměli.',
        32: 'I plavili se na lodí na pusté místo soukromí.',
        33: 'A vidouce je zástupové, že jdou pryč, poznali jej mnozí. I zběhli se tam ze všech měst pěšky, a předešli je, a shromáždili se k němu.',
        34: 'Tedy vyšed Ježíš, uzřel zástup mnohý, a slitovalo mu se jich, že byli jako ovce, nemajíce pastýře. I počal je učiti mnohým věcem.',
        35: 'A když se již prodlilo, přistoupivše k němu učedlníci jeho, řekli: Pustéť jest toto místo, a již se prodlilo.',
        36: 'Propusť je, ať jdouce do okolních vesnic a městeček, nakoupí sobě chleba; nebo nemají, co by jedli.',
        37: 'On pak odpověděv, řekl jim: Dejte vy jim jísti. I řkou jemu: Jdouce, koupíme za dvě stě grošů chleba, a dáme jim jísti?',
        38: 'I dí jim: Kolik chlebů máte? Jděte a zvězte. A když zvěděli, řekli: Pět, a dvě rybě.',
        39: 'I rozkázal jim, aby se kázali posaditi všechněm po houfích na zelené trávě.',
        40: 'I usadili se rozdílně, po stu a po padesáti.',
        41: 'A vzav těch pět chlebů a ty dvě rybě, popatřiv do nebe, dobrořečil, i lámal chleby, a dal učedlníkům svým, aby kladli před ně. A dvě rybě rozdělil mezi všecky.',
        42: 'I jedli všickni, a nasyceni jsou.',
        43: 'Potom sebrali drobtů dvanácte košů plných, i z ryb.',
        44: 'A bylo těch, kteříž jedli ty chleby, okolo pěti tisíců mužů.',
        45: 'A hned přinutil učedlníky své, aby vstoupili na lodí, a předešli jej přes moře k Betsaidě, až by on propustil zástup.',
        46: 'A propustiv je, šel na horu, aby se modlil.',
        47: 'A když byl večer, byla lodí u prostřed moře, a on sám na zemi.',
        48: 'A viděl je, a oni se s těžkostí plavili; (nebo byl vítr odporný jim.) A při čtvrtém bdění nočním přišel k nim, chodě po moři, a chtěl jich pominouti.',
        49: 'Oni pak uzřevše jej, an chodí po moři, domnívali se, že by obluda byla. I zkřikli.',
        50: '(Nebo jej všickni viděli, a zstrašili se.) Ale hned promluvil k nim a řekl jim: Doufejtež, jáť jsem, nebojte se.',
        51: 'I vstoupil k nim na lodí, a utišil se vítr; a oni mnohem více sami v sobě se děsili a divili.',
        52: 'Nebo nerozuměli z strany chlebů; bylo zajisté srdce jejich zhrublo.',
        53: 'A přeplavivše se, přišli do země Genezaretské, a tu lodí přistavili.',
        54: 'A když vyšli z lodí, hned jej poznali.',
        55: 'A běhajíce po vší krajině té, počali na ložcích nositi nemocné, kdežkoli uslyšeli o něm, že by byl.',
        56: 'A kamžkoli vcházel do městeček neb do měst neb do vsí, na ulicech kladli neduživé, a prosili ho, aby se aspoň podolka roucha jeho dotkli. A kolikož jich koli se jeho dotklo, uzdraveni byli.',
    },
    7: {
        1: 'I sešli se k němu farizeové a někteří z zákonníků, kteříž byli přišli z Jeruzaléma.',
        2: 'A uzřevše některé z učedlníků jeho obecnýma rukama, (to jest neumytýma,) jísti chleby, reptali o to.',
        3: 'Nebo farizeové i všickni Židé nejedí, leč by ruce umyli, držíce ustanovení starších.',
        4: 'A po trhu nejedí, leč se umyjí. A jiné mnohé věci jsou, kteréž přijali, aby je zachovávali, jako umývání koflíků, žejdlíků a medenic i stolů.',
        5: 'Potom otázali se ho farizeové a zákonníci: Proč učedlníci tvoji nezachovávají ustanovení starších, ale neumytýma rukama jedí chléb?',
        6: 'On pak odpověděv, řekl jim: Dobře prorokoval Izaiáš o vás pokrytcích, jakož psáno jest: Lid tento rty mne ctí, srdce pak jejich daleko jest ode mne.',
        7: 'Ale nadarmoť mne ctí, učíce učení a ustanovení lidská.',
        8: 'Nebo opustivše přikázaní Boží, držíte ustanovení lidská, umývání žejdlíků a koflíků, a jiné věci mnohé těm podobné činíte.',
        9: 'I pravil jim: Čistě vy rušíte přikázaní Boží, abyste ustanovení svá zachovali.',
        10: 'Nebo Mojžíš pověděl: Cti otce svého i matku svou, a kdož by zlořečil otci neb mateři, ať smrtí umře.',
        11: 'Ale vy pravíte: Řekl-li by člověk otci neb mateři: Korban, (totiž, dar jest to,) čímž by tobě ode mne pomoženo býti mohlo.',
        12: 'A nedopustíte mu nic více učiniti otci svému neb mateři své,',
        13: 'Rušíce slovo Boží ustanovením svým, kteréž jste ustanovili. A mnohé těm podobné věci činíte.',
        14: 'I svolav všecken zástup, pravil jim: Slyšte mne všickni a rozumějte.',
        15: 'Nic není z zevnitřku vcházejícího do člověka, což by jej poškvrniti mohlo; ale to, což pochází z něho, toť jest, což poškvrňuje člověka.',
        16: 'Má-li kdo uši k slyšení, slyš.',
        17: 'A když všel do domu od zástupu, tázali se ho učedlníci jeho o tom podobenství.',
        18: 'I řekl jim: Tak jste i vy nerozumní? Což nerozumíte, že všecko, což z zevnitřku do člověka vchází, nemůže ho poškvrniti?',
        19: 'Nebo nevchází v srdce jeho, ale v břicho, a potom ven vychází, čistěci všeliké pokrmy.',
        20: 'Pravil pak, že to, což pochází z člověka, to poškvrňuje člověka.',
        21: 'Nebo z vnitřku z srdce lidského zlá myšlení pocházejí, cizoložstva, smilstva, vraždy,',
        22: 'Krádeže, lakomství, nešlechetnosti, lest, nestydatost, oko zlé, rouhání, pýcha, bláznovství.',
        23: 'Všecky tyto zlé věci pocházejí z vnitřku, a poškvrňují člověka.',
        24: 'A vstav odtud, odšel do končin Týru a Sidonu, a všed do domu, nechtěl, aby kdo věděl, ale nemohl se tajiti.',
        25: 'Nebo uslyševši o něm žena, jejíž dcerka měla ducha nečistého, přišla a padla k nohám jeho.',
        26: '(Byla pak ta žena pohanka, Syrofenitská rodem.) I prosila ho, aby ďábelství vyvrhl z její dcery.',
        27: 'Ale Ježíš řekl jí: Nechať se prvé nasytí dítky; nebť není slušné vzíti chléb dětem a vrci štěňatům.',
        28: 'A ona odpověděla a řekla mu: Ovšem, Pane, nebo štěňátka jedí pod stolem drobty synů.',
        29: 'I řekl jí: Pro tu řeč jdi, vyšloť jest ďábelství z tvé dcery.',
        30: 'I odšedši do domu svého, nalezla děvečku, ana leží na loži, a ďábelství z ní vyšlo.',
        31: 'Tedy vyšed zase z končin Tyrských a Sidonských, přišel k moři Galilejskému, prostředkem krajin Desíti měst.',
        32: 'I přivedli jemu hluchého a zajikavého, a prosili ho, aby na něj ruku vzložil.',
        33: 'A pojav jej soukromí ven z zástupu, vložil prsty své v uši jeho, a plinuv, dotekl se jazyka jeho.',
        34: 'A vzezřev k nebi, vzdechl a řekl jemu: Efata, to jest, otevři se.',
        35: 'A hned otevříny jsou uši jeho, a rozvázán jest svazek jazyka jeho, i mluvil právě.',
        36: 'I přikázal jim, aby žádnému nepravili. Ale jakžkoli on jim přikazoval, oni mnohem více ohlašovali.',
        37: 'A převelmi se divili, řkouce: Dobře všecky věci učinil. I hluchým rozkázal slyšeti, i němým mluviti.',
    },
    8: {
        1: 'V těch dnech když velmi veliký zástup byl, a neměli, co by jedli, svolav Ježíš učedlníky své, řekl jim:',
        2: 'Lítost mám nad zástupy; nebo již tři dni trvají se mnou, a nemají, co by jedli.',
        3: 'A rozpustím-li je lačné do domů jejich, zhynou na cestě; nebo někteří z nich zdaleka přišli.',
        4: 'Odpověděli mu učedlníci jeho: I odkud bude moci kdo tyto nakrmiti chleby zde na poušti?',
        5: 'I otázal se jich: Kolik máte chlebů? A oni řekli: Sedm.',
        6: 'I kázal zástupu posaditi se na zemi. A vzav těch sedm chlebů, díky učiniv, lámal a dával učedlníkům svým, aby předkládali. I kladli před zástup.',
        7: 'A měli rybiček maličko. Jichž požehnav, kázal i ty před ně klásti.',
        8: 'I jedli a nasyceni jsou; a sebrali, což pozůstalo drobtů, sedm košů.',
        9: 'Těch pak, kteříž jedli, bylo okolo čtyř tisíců. I propustil je.',
        10: 'Potom hned vstoupiv na lodí s učedlníky svými, přeplavil se do krajin Dalmanutských.',
        11: 'I vyšli farizeové, a počali se s ním hádati, hledajíce od něho znamení s nebe, pokoušejíce ho.',
        12: 'A on vzdech duchem svým, dí: Co pokolení toto znamení hledá? Amen pravím vám: Nebude dáno znamení pokolení tomuto.',
        13: 'A opustiv je, vstoupil zase na lodí, i plavil se dále.',
        14: 'I zapomenuli s sebou vzíti chlebů, a neměli než jeden chléb s sebou na lodí.',
        15: 'Tedy přikazoval jim, řka: Vizte a pilně se šetřte kvasu farizejského a kvasu Heródesova.',
        16: 'I přemyšlovali, řkouce jeden k druhému: Chleba nemáme.',
        17: 'A znaje to Ježíš, řekl jim: Co přemyšlujete o tom, že chleba nemáte? Ještě neznáte, ani nerozumíte? Ještě máte oslepené své srdce?',
        18: 'Oči majíce, nevidíte? A uši majíce, neslyšíte? A nepomníte,',
        19: 'Že jsem pět chlebů lámal mezi pět tisíců? Kolik jste plných košů drobtů sebrali? Řekli jemu: Dvanácte.',
        20: 'A když také sedm chlebů mezi čtyři tisíce, kolik jste plných košů drobtů vzali? I řkou jemu: Sedm.',
        21: 'I řekl jim: Kterakž nerozumíte?',
        22: 'I přišel do Betsaidy, a přivedli k němu slepého, prosíce ho, aby se ho dotekl.',
        23: 'I ujav toho slepého za ruku, vyvedl jej ven z městečka, a plinuv na oči jeho, a vloživ na něj ruce, otázal se ho, viděl-li by co.',
        24: 'A on pohleděv zhůru, řekl: Znamenám lidi; nebo vidím, že chodí jako stromové.',
        25: 'Potom opět vložil ruce na oči jeho, a kázal mu hleděti zhůru. I uzdraven jest, tak že i zdaleka jasně viděl všecky.',
        26: 'I odeslal jej do domu jeho, řka: Aniž do toho městečka choď, aniž komu z městečka prav.',
        27: 'Tedy vyšel Ježíš a učedlníci jeho do městeček Cesaree Filipovy. A na cestě tázal se učedlníků svých, řka jim: Kým mne praví býti lidé?',
        28: 'Kteříž odpověděli: Janem Křtitelem, a jiní Eliášem, jiní pak jedním z proroků.',
        29: 'Tedy on řekl jim: Vy pak kým mne býti pravíte? Odpověděv Petr, řekl jemu: Ty jsi Kristus.',
        30: 'I přikázal jim s pohrůžkou, aby o něm žádnému nepravili.',
        31: 'I počal učiti je, že Syn člověka musí mnoho trpěti, a potupen býti od starších a předních kněží {biskupů} a zákonníků, a zabit býti, a ve třech dnech z mrtvých vstáti.',
        32: 'A zjevně to slovo mluvil. Protož chytiv jej Petr, počal mu domlouvati.',
        33: 'Kterýžto obrátiv se, a pohleděv na učedlníky své, přimluvil Petrovi, řka: Jdiž za mnou, satane; nebo nechápáš, co jest Božího, ale co lidského.',
        34: 'A svolav zástup s učedlníky svými, řekl jim: Chce-li kdo za mnou přijíti, zapři sebe sám, a vezmi kříž svůj, a následuj mne.',
        35: 'Nebo chtěl-li by kdo duši svou zachovati, ztratíť ji; pakli by kdo ztratil duši svou pro mne a pro evangelium, tenť ji zachová.',
        36: 'Nebo co prospěje člověku, by všecken svět získal, a své duši škodu učinil?',
        37: 'Aneb jakou dá člověk odměnu za duši svou?',
        38: 'Nebo kdož by se koli za mne styděl a za má slova v tomto pokolení cizoložném a hříšném, i Syn člověka styděti se bude za něj, když přijde v slávě Otce svého s anděly svatými.',
    },
    9: {
        1: 'I pravil jim: Amen pravím vám, žeť jsou někteří z stojících tuto, kteříž neokusí smrti, až i uzří království Boží přicházející v moci.',
        2: 'A po šesti dnech pojal Ježíš Petra a Jakuba a Jana, i uvedl je na horu vysokou soukromí samy, a proměnil se před nimi.',
        3: 'A učiněno jest roucho jeho stkvoucí a bílé velmi jako sníh, ješto tak bílého bělič na zemi učiniti nemůže.',
        4: 'I uzřeli Eliáše s Mojžíšem, ani s Ježíšem mluví.',
        5: 'A odpověděv Petr, řekl Ježíšovi: Mistře, dobréť jest nám tuto býti. Protož udělejme tři stánky, tobě jeden, Mojžíšovi jeden, a Eliášovi jeden.',
        6: 'Nebo nevěděl, co mluví; byli zajisté přestrašeni.',
        7: 'I stal se oblak zastěňující je, a přišel hlas z oblaku, řkoucí: Tentoť jest ten Syn můj milý, jeho poslouchejte.',
        8: 'A hned obezřevše se, žádného víc neviděli než samého Ježíše s sebou.',
        9: 'A když sstupovali s hory, přikázal jim, aby toho žádnému nevypravovali, co viděli, než až Syn člověka z mrtvých vstane.',
        10: 'I zachovali tu věc u sebe, tížíce mezi sebou, co by to bylo z mrtvých vstáti.',
        11: 'I otázali se ho, řkouce: Což to pak zákonníci praví, že Eliáš musí přijíti prvé?',
        12: 'On pak odpověděv, řekl jim: Eliáš přijda nejprvé, napraví všecky věci, a jakož psáno jest o Synu člověka, že musí mnoho trpěti, a za nic položen býti.',
        13: 'Ale pravím vám, že i Eliáš přišel, i učinili mu, což chtěli, jakož psáno jest o něm.',
        14: 'Tedy přišed k učedlníkům, uzřel zástup veliký okolo nich, a zákonníky, an se hádají s nimi.',
        15: 'A hned všecken zástup uzřev jej, ulekli se; a zběhše se, přivítali ho.',
        16: 'I otázal se zákonníků: Co se hádáte spolu?',
        17: 'A odpovídaje jeden z zástupu, řekl: Mistře, přivedl jsem syna svého k tobě, kterýž má ducha němého.',
        18: 'Ten kdyžkoli jej pochopí, lomcuje jím, a on se sliní, a škřipí zubami svými, a svadne. I řekl jsem učedlníkům tvým, aby jej vyvrhli, ale nemohli.',
        19: 'A on odpovídaje jemu, řekl: Ó národe nevěrný. Ale dokudž s vámi budu? A dokudž vás trpěti budu? Přiveďte jej ke mně.',
        20: 'I přivedli ho k němu. A jakž jej uzřel, hned ním duch lomcoval; a padna na zemi, válel se a slinil.',
        21: 'I otázal se otce jeho: Dávno-li se jemu to stalo? A on řekl: Od dětinství.',
        22: 'A často jím metal i na oheň i do vody, aby jej zahubil. Ale můžeš-li co, spomoz nám, slituje se nad námi.',
        23: 'A Ježíš řekl jemu: Můžeš-li tomu věřiti; všeckoť jest možné věřícímu.',
        24: 'A i hned zvolav otec mládence toho s slzami, řekl: Věřím, Pane, spomoz nedověře mé.',
        25: 'Uzřev pak Ježíš, že se zbíhá zástup, přimluvil duchu tomu nečistému, řka jemu: Duchu němý a hluchý, já tobě přikazuji, vyjdi z něho, a nevcházej více do něho.',
        26: 'Tedy křiče a velmi jím lomcuje, vyšel. I učiněn jest jako mrtvý, tak že mnozí pravili, že umřel.',
        27: 'Ale Ježíš ujav jej za ruku, pozdvihl ho. I vstal.',
        28: 'A když všel do domu, učedlníci jeho otázali se ho soukromí: Proč jsme my ho nemohli vyvrci?',
        29: 'I řekl jim: Toto pokolení nijakž nemůž vyjíti, jediné skrze modlitbu a půst.',
        30: 'A jdouce odtud, šli spolu skrze Galilei, ale nechtěl, aby kdo věděl.',
        31: 'Nebo učil učedlníky své a pravil jim: Že Syn člověka dán bude v ruce lidské, a zamordujíť jej, ale zamordován jsa, třetího dne z mrtvých vstane.',
        32: 'Oni pak nesrozuměli tomu povědění, a však ostýchali se ho otázati.',
        33: 'I přišel do Kafarnaum, a v domě byv, otázal se jich: Co jste na cestě mezi sebou rozjímali?',
        34: 'Ale oni mlčeli. Nebo hádali se byli na cestě mezi sebou, kdo by z nich byl větší.',
        35: 'A posadiv se, zavolal dvanácti, a dí jim: Chce-li kdo první býti, budeť ze všech nejposlednější a všech služebník.',
        36: 'A vzav pacholátko, postavil je u prostřed nich, a vzav je na lokty, řekl jim:',
        37: 'Kdož by koli jedno z takových pacholátek přijal ve jménu mém, mneť přijímá; a kdož by mne koli přijal, ne mneť přijímá, ale toho, kterýž mne poslal.',
        38: 'I odpověděl mu Jan, řka: Mistře, viděli jsme jednoho, an ve jménu tvém ďábly vymítá, kterýž nechodí s námi; i bránili jsme mu, proto že s námi nechodí.',
        39: 'Ježíš pak řekl: Nebraňtež mu. Neboť není žádného, kterýž by divy činil ve jménu mém, aby mohl snadně zle mluviti o mně.',
        40: 'Nebo kdož není proti nám, s námiť jest.',
        41: 'Kdož by koli zajisté dal vám píti číši vody ve jménu mém, proto že jste Kristovi, amen pravím vám, neztratíť nikoli odplaty své.',
        42: 'A kdož by koli pohoršil jednoho z těchto maličkých, věřících ve mne, mnohem by mu lépe bylo, aby byl zavěšen na hrdlo jeho žernov mlýnský a vržen byl do moře.',
        43: 'A horšila-li by tě ruka tvá, utni ji. Lépeť jest tobě bezrukému vjíti do života, nežli obě ruce majícímu jíti do pekla v ten oheň neuhasitelný,',
        44: 'Kdež červ jejich neumírá, a oheň nehasne.',
        45: 'A pakli noha tvá horšila by tě, utni ji. Lépeť jest tobě kulhavému vjíti do života, nežli obě noze majícímu uvrženu býti do pekla, v ten oheň neuhasitelný,',
        46: 'Kdež červ jejich neumírá, a oheň nehasne.',
        47: 'Pakli by tě oko tvé horšilo, vylup je. Lépeť jest tobě jednookému vjíti do království Božího, nežli obě oči majícímu uvrženu býti do ohně pekelného,',
        48: 'Kdež červ jejich neumírá, a oheň nehasne.',
        49: 'Nebo každý ohněm bude solen, a všeliká obět solí bude osolena.',
        50: 'Dobráť jest sůl. Pakli sůl bude neslaná, čím ji osolíte? Mějte sůl sami v sobě, a pokoj mějte mezi sebou.',
    },
    10: {
        1: 'A vstav odtud, přišel do končin Judských skrze krajinu za Jordánem ležící. I sešli se k němu zase zástupové, a jakž obyčej měl, opět je učil.',
        2: 'Tedy přistoupivše farizeové, otázali se ho: sluší-li muži propustiti ženu? pokoušejíce ho.',
        3: 'On pak odpovídaje, řekl jim: Co vám přikázal Mojžíš?',
        4: 'Kteříž řekli: Mojžíš dopustil lístek rozloučení napsati a propustiti.',
        5: 'I odpověděv Ježíš, řekl jim: Pro tvrdost srdce vašeho napsal vám to přikázaní.',
        6: 'Ale od počátku stvoření muže a ženu učinil je Bůh.',
        7: 'Protoť opustí člověk otce svého i matku, a přídržeti se bude ženy své.',
        8: 'I budou ti dva jedno tělo. A tak již nejsou dva, ale jedno tělo.',
        9: 'Protož což Bůh spojil, člověk nerozlučuj.',
        10: 'A v domě opět učedlníci jeho otázali se ho o též věci.',
        11: 'I dí jim: Kdož by koli propustil manželku svou a jinou pojal, cizoloží proti ní.',
        12: 'A jestliže by žena propustila muže svého a za jiného se vdala, cizoloží.',
        13: 'Tedy přinášeli k němu dítky, aby se jich dotýkal. Ale učedlníci přimlouvali těm, kteříž je nesli.',
        14: 'To viděv Ježíš, nelibě to nesl, a řekl jim: Nechte dítek jíti ke mně, a nebraňte jim, nebo takovýchť jest království Boží.',
        15: 'Amen pravím vám: Kdož by koli nepřijal království Božího jako dítě, nikoliť do něho nevejde.',
        16: 'A bera je na lokty své, a vzkládaje na ně ruce, požehnání jim dával.',
        17: 'Potom když vyšel na cestu, přiběhl jeden, a poklekna před ním, otázal se ho: Mistře dobrý, co učiním, abych života věčného dědičně došel?',
        18: 'I řekl mu Ježíš: Co mne nazýváš dobrým? Žádný není dobrý, než jediný Bůh.',
        19: 'Přikázaní umíš: Nezcizoložíš, nezabiješ, neukradneš, nevydáš falešného svědectví, neoklamáž, cti otce svého i matku.',
        20: 'A on odpověděv, řekl jemu: Mistře, toho všeho jsem ostříhal od své mladosti.',
        21: 'Tedy Ježíš pohleděv na něj, zamiloval ho, a řekl jemu: Jednohoť se nedostává. Jdi, a cožkoli máš, prodej, a dej chudým, a budeš míti poklad v nebi; a poď, následuj mne, vezma kříž.',
        22: 'On pak zarmoutiv se pro to slovo, odšel, truchliv jsa; nebo měl mnohá zboží.',
        23: 'A pohleděv vůkol Ježíš, dí učedlníkům svým: Jak nesnadně ti, kteříž statky mají, vejdou do království Božího.',
        24: 'Tedy učedlníci užasli se nad těmi řečmi jeho. Ježíš pak zase odpověděv, dí jim: Synáčkové, kterak nesnadné jest doufajícím v statek do království Božího vjíti.',
        25: 'Snáze jest velbloudu skrze jehelní ucho projíti, nežli bohatému vjíti do království Božího.',
        26: 'Oni pak více se děsili, řkouce mezi sebou: I kdož může spasen býti?',
        27: 'A pohleděv na ně Ježíš, dí: U lidíť jest nemožné, ale ne u Boha; nebo u Boha všecko možné jest.',
        28: 'I počal Petr mluviti k němu: Aj, my opustili jsme všecko, a šli jsme za tebou.',
        29: 'Odpověděv pak Ježíš, řekl: Amen pravím vám, žádného není, ješto by opustil dům, neb bratří, neb sestry, neb otce, neb matku, neb manželku, neb dítky, neb rolí pro mne a pro evangelium,',
        30: 'Aby nevzal stokrát tolik nyní v času tomto domů a bratrů a sester a matek a dítek a rolí s protivenstvím, a v budoucím věku život věčný.',
        31: 'Mnozíť pak první budou poslední, a poslední první.',
        32: 'Byli pak na cestě, jdouce do Jeruzaléma, a Ježíš šel napřed. I byli předěšeni, a jdouce za ním, báli se. Tedy pojav opět dvanácte, počal jim praviti, co se jemu má státi,',
        33: 'Řka: Aj, vstupujeme do Jeruzaléma, a Syn člověka vydán bude předním kněžím {biskupům} a zákonníkům i odsoudí jej na smrt, a vydadí jej pohanům.',
        34: 'Kteřížto posmívati se budou jemu, a ubičují ho, a uplijí i zabijí jej, ale třetího dne z mrtvých vstane.',
        35: 'Tedy přistoupili k němu Jakub a Jan, synové Zebedeovi, řkouce: Mistře, chceme, zač bychom koli prosili tebe, abys učinil nám.',
        36: 'On pak řekl jim: Co chcete, abych vám učinil?',
        37: 'I řekli jemu: Dej nám, abychom jeden na pravici tvé a druhý na levici tvé seděli v slávě tvé.',
        38: 'Ježíš pak řekl jim: Nevíte, zač prosíte. Můžete-li píti kalich, kterýž já piji, a křtíti se křtem, kterýmž já se křtím?',
        39: 'A oni řekli jemu: Můžeme. Ježíš pak řekl jim: Kalich zajisté, kterýž já piji, píti budete, a křtem, kterýmž já se křtím, křtěni budete,',
        40: 'Ale seděti na pravici mé neb na levici mé, neníť má věc dáti, ale kterýmž připraveno jest.',
        41: 'A uslyšavše to deset, počali se hněvati na Jakuba a na Jana.',
        42: 'Ale Ježíš povolav jich, řekl jim: Víte, že ti, kteříž sobě zalibují vládnouti nad národy, panujíť nad nimi; a kteříž velicí u nich jsou, moc provozují nad nimi.',
        43: 'Ne takť bude mezi vámi. Ale kdožkoli chtěl by mezi vámi býti veliký, budiž váš služebník.',
        44: 'A kdožkoli z vás chtěl by býti přední, budiž služebník všech.',
        45: 'Nebo i Syn člověka nepřišel, aby mu sloužili, ale aby sloužil, a aby dal duši svou na vykoupení za mnohé.',
        46: 'Tedy přišli do Jericho, a když vycházel on z Jericha, i učedlníci jeho a zástup mnohý, Timeův syn, Bartimeus slepý, seděl podlé cesty, žebře.',
        47: 'A když uslyšel, že by byl Ježíš Nazaretský, počal volati a říci: Ježíši, synu Davidův, smiluj se nade mnou.',
        48: 'I přimlouvali mu mnozí, aby mlčel. Ale on mnohem více volal: Synu Davidův, smiluj se nade mnou.',
        49: 'Tedy zastaviv se Ježíš, kázal ho zavolati. I zavolali toho slepého, řkouce jemu: Dobré mysli buď, vstaň, volá tě.',
        50: 'On pak povrh plášť svůj, a zchopiv se, šel k Ježíšovi.',
        51: 'I odpověděv Ježíš, dí jemu: Co chceš, ať učiním? A slepý řekl jemu: Mistře, ať vidím.',
        52: 'Tedy Ježíš řekl jemu: Jdi, víra tvá tě uzdravila. A hned prohlédl, a šel cestou za Ježíšem.',
    },
    11: {
        1: 'A když se přiblížili k Jeruzalému a Betfagi i Betany při hoře Olivetské, poslal dva z učedlníků svých.',
        2: 'A řekl jim: Jděte do městečka, kteréž proti vám jest, a hned vejdouce tam, naleznete oslátko přivázané, na kterémž nižádný z lidí neseděl. Odvížíce, přiveďte.',
        3: 'A řekl-liť by vám kdo: Co to činíte? rcete: Že ho Pán potřebuje. A hned je pošle sem.',
        4: 'I odešli, a nalezli oslátko přivázané vně u dveří na rozcestí. I odvázali je.',
        5: 'Tedy někteří z těch, kteříž tu stáli, řekli jim: Co činíte, odvazujíce oslátko?',
        6: 'Oni pak řekli jim, jakož byl přikázal Ježíš. I nechali jich.',
        7: 'Protož přivedli oslátko k Ježíšovi, a vložili na ně roucha svá. I vsedl na ně.',
        8: 'Mnozí pak stlali roucha svá na cestě, a jiní ratolesti sekali z stromů, a metali na cestu.',
        9: 'A kteříž napřed šli, i ti, kteříž za ním šli, volali, řkouce: Hosanna. Požehnaný, kterýž se béře ve jménu Páně.',
        10: 'Požehnané království otce našeho Davida, kteréž přišlo ve jménu Páně. Hosanna na výsostech.',
        11: 'I všel do Jeruzaléma Ježíš, i do chrámu. A spatřiv tu všecko, když již byla večerní hodina, vyšel do Betany se dvanácti.',
        12: 'A druhého dne, když vycházel z Betany, zlačněl.',
        13: 'A uzřev z daleka fík, an má lístí, šel, zda by co nalezl na něm. A když přišel k němu, nic nenalezl kromě lístí; nebo nebyl čas fíků.',
        14: 'Tedy odpověděv Ježíš, řekl jemu: Již více na věky nižádný z tebe ovoce nejez. A slyšeli to učedlníci jeho.',
        15: 'I přišli do Jeruzaléma. A všed Ježíš do chrámu, počal vymítati ty, kteříž prodávali a kupovali v chrámě, a stoly penězoměnců a stolice prodávajících holuby převracel.',
        16: 'A nedopustil, aby kdo nádobu nesl skrze chrám.',
        17: 'I učil je, řka jim: Zdaliž není psáno, že dům můj dům modlitby slouti bude u všech národů? Vy pak učinili jste jej peleší lotrů.',
        18: 'Slyšeli pak to zákonníci i přední kněží {biskupové}, a hledali, kterak by jej zahubili; nebo se ho báli, proto že všecken zástup divil se učení jeho.',
        19: 'A když byl večer, vyšel z města.',
        20: 'A jdouce ráno, uzřeli ten fík, an usechl z kořene.',
        21: 'Tedy zpomenuv Petr, řekl jemu: Mistře, aj, ten fík, kterémuž jsi zlořečil, usechl.',
        22: 'I odpověděv Ježíš, řekl jim: Mějte víru Boží.',
        23: 'Nebo amen pravím vám, že kdož by koli řekl hoře této: Zdvihni se a vrz sebou do moře, a nepochyboval by v srdci svém, ale věřil by, že se stane, cožkoli dí, staneť se jemu tak, což by koli řekl.',
        24: 'Protož pravím vám: Zač byste koli, modléce se, prosili, věřte, že vezmete, a staneť se vám.',
        25: 'A když se postavíte k modlení, odpouštějte, máte-li co proti komu, aby i Otec váš nebeský odpustil vám hříchy vaše.',
        26: 'Nebo jestliže vy neodpustíte, ani Otec váš, kterýž v nebesích jest, odpustí vám hříchů vašich.',
        27: 'I přišli zase do Jeruzaléma. A když on procházel se v chrámě, přistoupili k němu přední kněží {biskupové} a zákonníci a starší.',
        28: 'I řekli jemu: Jakou mocí to činíš? A kdo tobě dal tu takovou moc, abys tyto věci činil?',
        29: 'Tedy odpovídaje Ježíš, řekl jim: Otížiť se i já vás na jednu věc. Odpovězte mi, a povím vám, jakou mocí to činím.',
        30: 'Křest Janův s nebe-li byl, čili z lidí? Odpovězte mi.',
        31: 'I rozjímali sami mezi sebou, řkouce: Díme-li: S nebe, díť: Proč jste tedy neuvěřili jemu?',
        32: 'Pakli díme: Z lidí, bojíme se lidu. Nebo všickni o Janovi smyslili, že právě byl prorok.',
        33: 'I odpověděvše, řekli Ježíšovi: Nevíme. A Ježíš odpovídaje, řekl jim: Aniž já vám povím, jakou mocí to činím.',
    },
    12: {
        1: 'Tedy počal jim mluviti v podobenstvích: Vinici štípil člověk, a opletl ji plotem, a vkopal pres, a ustavěl věži, a pronajal ji vinařům, i odšel na cestu.',
        2: 'A když toho čas byl, poslal k vinařům služebníka, aby od vinařů vzal ovoce z vinice.',
        3: 'Oni pak javše jej, zmrskali ho, a odeslali prázdného.',
        4: 'I poslal k nim zase jiného služebníka. I toho též kamenovavše, ranili v hlavu, a odeslali zohaveného.',
        5: 'I poslal opět jiného. I toho zabili, a mnoho jiných, z nichž některé zmrskali, a jiné zmordovali.',
        6: 'Ještě pak maje jediného syna milého, i toho poslal k nim naposledy, řka: Ustýdnouť se syna mého.',
        7: 'Ale vinaři řekli jedni k druhým: Tentoť jest dědic; poďte, zabíme jej, a budeť naše dědictví.',
        8: 'Tedy javše jej, zabili ho, a vyvrhli ven z vinice.',
        9: 'Což tedy učiní pán vinice? Přijde, a zatratí vinaře ty, a dá vinici jiným.',
        10: 'Zdaliž jste písma toho nečtli? Kámen, kterýž zavrhli stavitelé, ten učiněn jest hlavou úhlovou.',
        11: 'Ode Pána stalo se toto, a jest divné před očima našima.',
        12: 'I hledali ho jíti, ale báli se zástupu; nebo poznali, že podobenství to proti nim pověděl. A nechavše ho, odešli pryč.',
        13: 'Potom poslali k němu některé z farizeů a Herodiánů, aby jej polapili v řeči.',
        14: 'Kteřížto přišedše, řekli jemu: Mistře, víme, že jsi pravdomluvný, a nedbáš na žádného; nebo nepatříš na osobu lidskou, ale v pravdě cestě Boží učíš. Sluší-li daň dávati císaři, čili nic? Dáme-liž, čili nedáme?',
        15: 'On pak znaje pokrytství jejich, řekl jim: Co mne pokoušíte? Přineste mi peníz, ať pohledím.',
        16: 'A oni podali. Tedy řekl jim: Čí jest tento obraz a nápis? A oni řekli mu: Císařův.',
        17: 'I odpověděv Ježíš, řekl jim: Dávejtež tedy, což jest císařova, císaři, a což jest Božího, Bohu. I podivili se tomu.',
        18: 'Potom přišli k němu saduceové, kteříž praví, že není z mrtvých vstání. I otázali se ho, řkouce:',
        19: 'Mistře, Mojžíš nám napsal: Kdyby čí bratr umřel, a ostavil manželku, a synů by neměl, aby bratr jeho pojal manželku jeho, a vzbudil símě bratru svému.',
        20: 'I bylo sedm bratrů. A první pojav manželku, a umřev, nepozůstavil semene.',
        21: 'A druhý pojav ji, také umřel, a aniž ten ostavil semene. A třetí tolikéž.',
        22: 'A tak ji pojalo těch sedm, a nezůstavili semene. Nejposléze pak po všech umřela i ta žena.',
        23: 'Protož při vzkříšení, když z mrtvých vstanou, čí z těch bude manželka? Nebo jich sedm mělo ji za manželku.',
        24: 'A odpovídaje Ježíš, řekl jim: Zdaliž ne proto bloudíte, že neznáte písem ani moci Boží?',
        25: 'Nebo když vstanou z mrtvých, nebudou se ženiti ani vdávati, ale budou jako andělé nebeští.',
        26: 'O mrtvých pak, že mají vstáti, zdaliž jste nečtli v knize Mojžíšově, kterak ve kři promluvil k němu Bůh, řka: Já jsem Bůh Abrahamův, a Bůh Izákův, a Bůh Jákobův?',
        27: 'Neníť Bůh mrtvých, ale Bůh živých. Protož vy velmi bloudíte.',
        28: 'Tedy přistoupil jeden z zákonníků, slyšev je spolu se hádající, a vida, že jim dobře odpověděl, otázal se ho: Které jest přikázaní první ze všech?',
        29: 'A Ježíš odpověděl jemu, že první ze všech přikázaní jest: Slyš, Izraeli, Pán Bůh náš Pán jeden jest.',
        30: 'Protož milovati budeš Pána Boha svého ze všeho srdce svého, a ze vší duše své, a ze vší mysli své, i ze všech mocí svých. To jest první přikázaní.',
        31: 'Druhé pak podobné toto: Milovati budeš bližního svého jako sebe samého. Většího přikázaní jiného nad tato není.',
        32: 'I řekl jemu ten zákonník: Mistře, dobře jsi v pravdě pověděl. Nebo jeden jest Bůh, a není jiného kromě něho;',
        33: 'A milovati ho ze všeho srdce, a ze vší mysli, a ze vší duše, i ze všech mocí, a milovati bližního jako sebe samého jest nade všecky zápaly a oběti.',
        34: 'A viděv Ježíš, že by moudře odpověděl, dí jemu: Nejsi daleko od království Božího. A žádný více nesměl se ho tázati.',
        35: 'I odpovídaje Ježíš, řekl, uče v chrámě: Kterak praví zákonníci, že Kristus jest syn Davidův?',
        36: 'Nebo David praví v Duchu svatém: Řekl Pán Pánu mému: Seď na pravici mé, ažť i položím nepřátely tvé za podnože noh tvých.',
        37: 'Poněvadž sám David nazývá jej Pánem, kterakž tedy syn jeho jest? A mnohý zástup rád ho poslouchal.',
        38: 'I mluvil jim v učení svém: Varujte se zákonníků, kteříž chtějí v krásném rouše choditi, a pozdravováni býti na trzích,',
        39: 'A na předních stolicech seděti v školách, a přední místa míti na večeřech,',
        40: 'Kteřížto zžírají domy vdovské, a to pod zámyslem dlouhých modliteb. Tiť vezmou soud těžší.',
        41: 'A posadiv se Ježíš proti pokladnici, díval se, kterak zástup metal peníze do pokladnice. A mnozí bohatí metali mnoho.',
        42: 'A přišedši jedna chudá vdova, i vrhla dva šarty, což jest čtvrtá částka peníze.',
        43: 'I svolav učedlníky své, dí jim: Amen pravím vám, že tato chudá vdova více uvrhla, než tito všickni, kteříž metali do pokladnice.',
        44: 'Nebo všickni z toho, což jim zbývalo, metali, ale tato z své chudoby, všecko, což měla, uvrhla, všecku živnost svou.',
    },
    13: {
        1: 'A když vycházel z chrámu, dí jemu jeden z učedlníků jeho: Mistře, pohleď, kteraké kamení a jaké stavení!',
        2: 'Tedy Ježíš odpovídaje, řekl jemu: Vidíš tato tak veliká stavení? Nebudeť ostaven kámen na kameni, kterýž by nebyl zbořen.',
        3: 'A když se posadil na hoře Olivetské proti chrámu, otázali se jeho soukromí Petr, Jakub a Jan a Ondřej:',
        4: 'Pověz nám, kdy to bude? A které znamení, když se toto všecko bude plniti?',
        5: 'Ježíš pak odpovídaje jim, počal praviti: Vizte, aby vás někdo nesvedl.',
        6: 'Neboť mnozí přijdou ve jménu mém, řkouce: Já jsem Kristus, a mnohéť svedou.',
        7: 'Když pak uslyšíte o boji a pověst o válkách, nestrachujte se; nebo musí to býti, ale ne i hned konec.',
        8: 'Povstaneť zajisté národ proti národu a království proti království, a budou země třesení po místech, a hladové i bouřky.',
        9: 'A toť počátkové bolestí. Vy pak šetřte se. Nebo vydávati vás budou na sněmy a do shromáždění; budete biti, a před vládaři a králi stanete pro mne, na svědectví jim.',
        10: 'Ale ve všech národech nejprv musí býti kázáno evangelium.',
        11: 'Když pak vás povedou, vyzrazujíce, nestarejte se předtím, co byste mluvili, aniž pečlivě přemyšlujte, ale což vám bude dáno v tu hodinu, to mluvte; nebo nejste vy, kteříž mluvíte, ale Duch svatý.',
        12: 'Vydáť pak bratr bratra na smrt a otec syna, a povstanou děti proti rodičům, a budou je mordovati.',
        13: 'A budete v nenávisti všechněm pro jméno mé. Ale kdož setrvá až do konce, tenť spasen bude.',
        14: 'Když pak uzříte ohavnost zpuštění, o kteréž povědíno jest skrze Daniele proroka, ana stojí, kdež by státi neměla, (kdo čte, rozuměj,) tehdáž ti, kdož by v Židovstvu byli, ať utekou na hory.',
        15: 'A kdož by na střeše byl, nesstupuj do domu, ani vcházej, aby co vzal z domu svého.',
        16: 'A kdo na poli, nevracuj se zase, aby vzal roucho své.',
        17: 'Běda pak těhotným a těm, kteréž krmí v těch dnech.',
        18: 'Protož modlte se, aby utíkání vaše nebylo v zimě.',
        19: 'Neboť budou ti dnové ssoužení, jakéhož nebylo od počátku stvoření, kteréž Bůh stvořil, až dosavad, aniž bude.',
        20: 'A byť nebyl ukrátil Pán těch dnů, nebyl by spasen žádný člověk. Ale pro vyvolené, kteréž vyvolil, ukrátil těch dnů.',
        21: 'A tehdáž řekl-li by vám kdo: Aj, teď jest Kristus, aneb aj, tamto, nevěřte.',
        22: 'Neboť povstanou falešní Kristové a falešní proroci, a budou činiti divy a zázraky k svedení, by možné bylo, také i vyvolených.',
        23: 'Vy pak šetřte se. Aj, předpověděl jsem vám všecko.',
        24: 'V těch pak dnech, po ssoužení tom, slunce se zatmí, a měsíc nedá světla svého.',
        25: 'A hvězdy nebeské budou padati, a moci, které jsou na nebi, pohnou se.',
        26: 'A tehdážť uzří Syna člověka, an se béře v oblacích s mocí velikou a s slávou.',
        27: 'I tehdyť pošle anděly své, a shromáždí vyvolené své ode čtyř větrů, od končin země až do končin nebe.',
        28: 'Od fíku pak učte se podobenství tomuto: Když již ratolest jeho odmladne, a vypučí se lístí, znáte, že blízko jest léto.',
        29: 'Takž i vy, když uzříte, ano se tyto věci dějí, vězte, že blízko jest a ve dveřích.',
        30: 'Amen pravím vám, žeť nepomine pokolení toto, až se tyto všecky věci stanou.',
        31: 'Nebe a země pominou, ale slova má nikoli nepominou.',
        32: 'Ale o tom dni a hodině žádný neví, ani andělé, kteříž jsou v nebesích, ani Syn, jediné Otec.',
        33: 'Vizte, bděte a modlte se; nebo nevíte, kdy bude ten čas.',
        34: 'Jako člověk, kterýž daleko odšel, opustiv dům svůj, a poručiv služebníkům svým vládařství, a jednomu každému práci jeho, vrátnému přikázal, aby bděl.',
        35: 'Protož bděte; nebo nevíte, kdy Pán domu přijde, u večer-li, čili o půlnoci, čili když kohouti zpívají, čili ráno.',
        36: 'Aby snad přijda v nenadále, nenalezl vás, a vy spíte.',
        37: 'A cožť vám pravím, všechněmť pravím: Bděte.',
    },
    14: {
        1: 'Po dvou pak dnech byl hod beránka a přesnic; i hledali přední kněží {biskupové} a zákonníci, kterak by jej lstivě jmouce, zamordovali.',
        2: 'Ale pravili: Ne v svátek, aby snad nebyl rozbroj v lidu.',
        3: 'A když byl v Betany, v domu Šimona malomocného, a seděl za stolem, přišla žena, mající nádobu alabastrovou masti velmi drahé, z nardového koření. A rozbivši alabastrovou nádobu, vylila ji na hlavu jeho.',
        4: 'I hněvali se někteří mezi sebou, řkouce: I proč ztráta masti této stala se?',
        5: 'Nebo mohlo toto prodáno býti, dráže než za tři sta peněz, a dáno býti chudým. I zpouzeli se na ni.',
        6: 'Ale Ježíš řekl: Nechte jí. Proč ji rmoutíte? Dobrýť skutek učinila nade mnou.',
        7: 'Však chudé máte vždycky s sebou, a když budete chtíti, můžete jim dobře činiti, ale mne ne vždycky míti budete.',
        8: 'Ona což mohla, to učinila; předešlať, aby těla mého pomazala ku pohřebu.',
        9: 'Amen pravím vám: Kdežkoli bude kázáno toto evangelium po všem světě, takéť i to, což učinila tato, bude vypravováno na památku její.',
        10: 'Tedy Jidáš Iškariotský, jeden ze dvanácti, odšel k předním kněžím {biskupům}, aby jim ho zradil.',
        11: 'Oni pak uslyševše, zradovali se, a slíbili mu peníze dáti. I hledal, kterak by ho příhodně zradil.',
        12: 'Prvního pak dne přesnic, když velikonoční beránek zabíjín býval, řkou jemu učedlníci jeho: Kde chceš, ať jdouce, připravíme, abys jedl beránka?',
        13: 'I poslal dva z učedlníků svých, a řekl jim: Jděte do města, a potkáť vás člověk dčbán vody nesa. Jdětež za ním.',
        14: 'A kamžkoli vejde, rcete hospodáři: Mistrť praví: Kde jest večeřadlo, v němž bych jedl beránka s učedlníky svými?',
        15: 'A on vám ukáže večeřadlo veliké, podlážené a připravené. Tu nám připravte.',
        16: 'I odešli učedlníci jeho, a přišli do města, a nalezli tak, jakož jim byl pověděl. I připravili beránka.',
        17: 'Když pak byl večer, přišel se dvanácti.',
        18: 'A když seděli za stolem a jedli, řekl Ježíš: Amen pravím vám, že jeden z vás mne zradí, kterýž jí se mnou.',
        19: 'A oni se počali rmoutiti, a praviti jemu jeden každý obzvláštně: Zdali já jsem? A jiný: Zdali já?',
        20: 'On pak odpověděv, řekl jim: Jeden ze dvanácti, kterýž omáčívá se mnou v mise.',
        21: 'Syn zajisté člověka jde, jakož psáno o něm, ale běda člověku tomu, skrze něhož Syn člověka bude zrazen. Dobré by bylo jemu, aby se byl nenarodil člověk ten.',
        22: 'A když oni jedli, vzav Ježíš chléb, a dobrořečiv, lámal a dával jim, řka: Vezměte, jezte, to jest tělo mé.',
        23: 'A vzav kalich, a díky učiniv, dal jim. A pili z něho všickni.',
        24: 'I řekl jim: To jest krev má smlouvy té nové, kteráž se za mnohé vylévá.',
        25: 'Amen pravím vám, žeť již více nikoli nebudu píti z plodu vinného kořene, až do onoho dne, když jej píti budu nový v království Božím.',
        26: 'A sezpívavše písničku, vyšli na horu Olivetskou.',
        27: 'Potom řekl jim Ježíš: Všickni vy zhoršíte se nade mnou této noci. Nebo psáno jest: Bíti budu pastýře, a rozprchnou se ovce.',
        28: 'Ale když z mrtvých vstanu, předejduť vás do Galilee.',
        29: 'Tedy Petr řekl jemu: Byť se pak všickni zhoršili, ale já nic.',
        30: 'I řekl jemu Ježíš: Amen pravím tobě, že dnes této noci, prvé než kohout po dvakrát zazpívá, třikrát mne zapříš.',
        31: 'On pak mnohem více mluvil: Bychť pak měl s tebou i umříti, nikoliť nezapřím tebe. A takž také i všickni mluvili.',
        32: 'I přišli na místo, kterémuž jméno Getsemany. Tedy řekl učedlníkům svým: Seďtež tuto, až se pomodlím.',
        33: 'A pojav s sebou Petra a Jakuba a Jana, počal se lekati a velmi teskliv býti.',
        34: 'I dí jim: Smutnáť jest duše má až k smrti. Počekejtež tuto a bděte.',
        35: 'A poodšed maličko, padl na zemi a modlil se, aby, bylo-li by možné, odešla od něho hodina ta.',
        36: 'I řekl: Abba, Otče, všecko jest možné tobě. Přenes kalich tento ode mne, ale však ne, což já chci, ale co ty.',
        37: 'I přišel a nalezl je, ani spí. I řekl Petrovi: Šimone, spíš? Nemohl-lis jediné hodiny bdíti?',
        38: 'Bděte a modlte se, abyste nevešli v pokušení. Duchť zajisté hotov jest, ale tělo nemocno.',
        39: 'A opět odšed, modlil se, táž slova mluvě.',
        40: 'A navrátiv se, nalezl je, ani opět spí, (nebo oči jejich byly obtíženy;) aniž věděli, co by jemu odpověděli.',
        41: 'I přišel po třetí, a řekl jim: Spětež již a odpočívejte; dostiť jest. Přišlať ta hodina; aj, Syna člověka zrazují v ruce hříšných.',
        42: 'Vstaňte, poďme. Aj, kterýž mne zrazuje, blízkoť jest.',
        43: 'A hned, když on ještě mluvil, přišel Jidáš, kterýž byl jeden ze dvanácti, a s ním zástup veliký s meči a s kyjmi, od předních kněží {biskupů} a od zákonníků a starších.',
        44: 'Zrádce pak jeho byl jim dal znamení, řka: Kteréhožkoli políbím, tenť jest; jmětež ho, a veďte opatrně.',
        45: 'A přišed, hned přistoupiv k němu, řekl: Mistře, Mistře, a políbil ho.',
        46: 'Tedy oni vztáhli naň ruce své, a jali jej.',
        47: 'Jeden pak z těch, kteříž tu okolo stáli, vytrh meč, udeřil služebníka nejvyššího kněze {biskupova}, a uťal jemu ucho.',
        48: 'I odpověděv Ježíš, řekl jim: Jako na lotra vyšli jste s meči a s kyjmi, abyste mne jali?',
        49: 'Na každý den býval jsem u vás, uče v chrámě, a nejali jste mne. Ale aby se naplnila písma.',
        50: 'Tedy opustivše jej, všickni utekli.',
        51: 'Jeden pak mládenček šel za ním, odín jsa rouchem lněným po nahém těle. I popadli jej mládenci.',
        52: 'On pak opustiv roucho, nahý utekl od nich.',
        53: 'I přivedli Ježíše k nejvyššímu knězi {biskupovi}, a sešli se k němu všickni přední kněží {biskupové} i starší i zákonníci.',
        54: 'Petr pak šel za ním zdaleka až na dvůr nejvyššího kněze {biskupův}; i seděl s služebníky, zhřívaje se u ohně.',
        55: 'Ale přední kněží {biskupové} i všecka ta rada hledali proti Ježíšovi svědectví, aby jej na smrt vydali, a však nenalezli.',
        56: 'Nebo ač mnozí křivé svědectví vydávali proti němu, však svědectví jejich nebyla jednostejná.',
        57: 'Tedy někteří povstavše, křivé svědectví dávali proti němu, řkouce:',
        58: 'My jsme slyšeli tohoto, že řekl: Já zbořím chrám tento rukou udělaný, a ve třech dnech jiný ne rukou udělaný postavím.',
        59: 'Ale ani to jejich svědectví nebylo jednostejné.',
        60: 'Tedy povstav nejvyšší kněz {biskup} u prostřed, otázal se Ježíše, řka: Neodpovídáš ničeho, což tito na tebe svědčí?',
        61: 'Ale on mlčel, a nic neodpověděl. Opět nejvyšší kněz {biskup} otázal se ho a řekl jemu: Jsi-liž ty Kristus, ten Syn toho Požehnaného?',
        62: 'A Ježíš řekl: Jáť jsem, a uzříte Syna člověka, an sedí na pravici moci Boží, a přichází s oblaky nebeskými.',
        63: 'Tedy nejvyšší kněz {biskup} roztrh roucha svá, řekl: I což ještě potřebujeme svědků?',
        64: 'Slyšeli jste rouhání. Co se vám zdá? Oni pak všickni potupili jej, že jest hoden smrti.',
        65: 'I počali někteří naň plvati, a tvář jeho zakrývati, a jej poličkovati, a říkati jemu: Prorokuj. A služebníci kyji jej bili.',
        66: 'A když byl Petr v síni dole, přišla jedna z děvek nejvyššího kněze {biskupových}.',
        67: 'A uzřevši Petra, an se ohřívá, a popatřivši naň, dí: I ty s Ježíšem Nazaretským byl jsi.',
        68: 'Ale on zapřel, řka: Aniž vím, ani rozumím, co ty pravíš. I vyšel ven před síň, a kohout zazpíval.',
        69: 'Tedy děvka, uzřevši jej opět, počala praviti těm, kteříž tu okolo stáli, že tento z nich jest.',
        70: 'A on opět zapřel. A po malé chvíli opět ti, kteříž tu stáli, řekli Petrovi: Jistě z nich jsi, nebo i Galilejský jsi, i řeč tvá podobná jest.',
        71: 'On pak počal se proklínati a přisahati: Neznám člověka toho, o němž pravíte.',
        72: 'A hned po druhé kohout zazpíval. I rozpomenul se Petr na slovo, kteréž byl řekl jemu Ježíš: Že prvé než kohout dvakrát zazpívá, třikrát mne zapříš. A vyšed, plakal.',
    },
    15: {
        1: 'A hned ráno, uradivše se přední kněží {biskupové} s staršími a s zákonníky i se vším shromážděním, svázavše Ježíše, vedli jej a dali Pilátovi.',
        2: 'I otázal se ho Pilát: Ty-li jsi ten král Židovský? A on odpověděv, řekl jemu: Ty pravíš.',
        3: 'I žalovali na něj přední kněží {biskupové} mnoho. On pak nic neodpovídal.',
        4: 'Tedy Pilát otázal se ho opět, řka: Nic neodpovídáš? Hle, jak mnoho proti tobě svědčí.',
        5: 'Ale Ježíš předce nic neodpověděl, tak že se podivil Pilát.',
        6: 'V svátek pak propouštíval jim jednoho z vězňů, za kteréhož by koli prosili.',
        7: 'I byl jeden, kterýž sloul Barabáš, s svárlivými v vězení, kteříž v svadě vraždu byli spáchali.',
        8: 'A zvolav zástup, počal prositi, aby učinil, jakož jim vždycky činíval.',
        9: 'Pilát pak odpověděl jim, řka: Chcete-li, propustím vám krále Židovského?',
        10: '(Nebo věděl, že jej z závisti vydali přední kněží {biskupové}.)',
        11: 'Ale přední kněží {biskupové} ponukli zástupu, aby jim raději propustil Barabáše.',
        12: 'A Pilát odpověděv, řekl jim zase: Což pak chcete, ať učiním tomu, kteréhož králem Židovským nazýváte?',
        13: 'A oni opět zvolali: Ukřižuj ho.',
        14: 'A Pilát pravil jim: I co zlého učinil? Oni pak více volali: Ukřižuj ho.',
        15: 'Tedy Pilát, chtě lidu dosti učiniti, pustil jim Barabáše, a dal jim Ježíše ubičovaného, aby byl ukřižován.',
        16: 'Žoldnéři pak uvedli jej vnitř do síně, do rathouzu, a svolali všecku zběř.',
        17: 'I oblékli jej v šarlat, a korunu zpletše z trní, vložili naň.',
        18: 'I počali ho pozdravovati: Zdráv buď, králi Židovský.',
        19: 'A bili hlavu jeho třtinou, a plili na něj, a sklánějíce kolena, klaněli se jemu.',
        20: 'A když se jemu naposmívali, svlékli s něho šarlat, a oblékli jej v roucho jeho vlastní. I vedli jej, aby ho ukřižovali.',
        21: 'I přinutili nějakého Šimona Cyrenenského, pomíjejícího, (kterýž šel z pole, otce Alexandrova a Rufova,) aby nesl kříž jeho.',
        22: 'I vedli jej až na místo Golgota, to jest, (vyložil-li by,) popravné místo.',
        23: 'I dávali mu píti víno s mirrou, ale on nepřijal.',
        24: 'A ukřižovavše jej, rozdělili roucha jeho, mecíce o ně los, kdo by co vzíti měl.',
        25: 'A byla hodina třetí, když ho ukřižovali.',
        26: 'A byl nápis viny jeho napsán: Král Židovský.',
        27: 'Ukřižovali také s ním dva lotry, jednoho na pravici, a druhého na levici jeho.',
        28: 'I naplněno jest písmo, řkoucí: A s nepravými počten jest.',
        29: 'A kteříž chodili mimo něj, rouhali se jemu, potřásajíce hlavami svými, a říkajíce: Hahá, kterýž rušíš chrám, a ve třech dnech vzděláváš,',
        30: 'Spomoz sobě samému, a sstup s kříže.',
        31: 'Též i přední kněží {biskupové} posmívajíce se, jeden k druhému s zákonníky pravili: Jinýmť pomáhal, sám sobě pomoci nemůže.',
        32: 'Kristus, ten král Izraelský, nechažť nyní sstoupí s kříže, ať uzříme, a uvěříme. A i ti, kteříž s ním ukřižování byli, útržku mu činili.',
        33: 'A když byla hodina šestá, stala se tma po vší zemi až do hodiny deváté.',
        34: 'A v hodinu devátou zvolal Ježíš hlasem velikým, řka: Elói, Elói, lama zabachtani? Což se vykládá: Bože můj, Bože můj, pročs mne opustil?',
        35: 'A někteří z okolo stojících, slyševše to, pravili: Hle, Eliáše volá.',
        36: 'A běžev jeden, naplnil hubu octem, a vloživ na tresť, dával jemu píti, řka: Ponechte, uzříme, přijde-li Eliáš, aby jej složil.',
        37: 'Ježíš pak zvolav hlasem velikým, pustil duši.',
        38: 'A opona v chrámě roztrhla se na dvé, od vrchu až dolů.',
        39: 'Viděv pak centurio, kterýž tu naproti stál, že tak volaje, vypustil duši, řekl: Jistě člověk tento Syn Boží byl.',
        40: 'Byly pak tu i ženy, zdaleka se dívajíce, mezi nimiž byla Maria Magdaléna, a Maria Jakuba menšího, a Jozesova mátě, a Salome,',
        41: 'Kteréž, když ještě byl v Galilei, chodily za ním a posluhovaly jemu, i jiné mnohé, kteréž byly s ním vstoupily do Jeruzaléma.',
        42: 'A když již byl večer, (že byl den připravování, to jest před sobotou,)',
        43: 'Přišed Jozef z Arimatie, počestná osoba úřadná, kterýž také očekával království Božího, směle všel ku Pilátovi, a prosil za tělo Ježíšovo.',
        44: 'Pilát pak podivil se, již-li by umřel. A povolav centuriona, otázal se ho, dávno-li je umřel.',
        45: 'A zvěděv od centuriona, dal tělo Jozefovi.',
        46: 'I koupiv plátna, a sňav ho, obvinul v plátno, a položil do hrobu, kterýž byl vytesán z skály, a přivalil kámen ke dveřům hrobovým.',
        47: 'Ale Maria Magdaléna a Maria Jozesova dívaly se, kde by byl položen.',
    },
    16: {
        1: 'A když pominula sobota, Maria Magdaléna a Maria Jakubova a Salome nakoupily vonných věcí, aby přijdouce, pomazaly Ježíše.',
        2: 'Protož velmi ráno v první den po sobotě přišly k hrobu, an již slunce vzešlo.',
        3: 'I pravily vespolek: Kdo nám odvalí kámen ode dveří hrobových?',
        4: '(A vzhlédše, uzřely odvalený kámen.) Byl zajisté veliký velmi.',
        5: 'A všedše do hrobu, uzřely mládence, an sedí na pravici, oděného rouchem bílým. I ulekly se.',
        6: 'On pak řekl jim: Nebojte se. Ježíše hledáte Nazaretského, toho ukřižovaného. Vstalť jest, neníť ho tuto; aj, místo, kdež jej byli položili.',
        7: 'Ale jděte, povězte učedlníkům jeho i Petrovi, žeť vás předejde do Galilee. Tam jej uzříte, jakž pověděl vám.',
        8: 'A vyšedše rychle, utekly od hrobu; nebo přišel na ně strach a hrůza. A aniž komu co řekly, nebo se bály.',
        9: 'Vstav pak Ježíš z mrtvých ráno v neděli, ukázal se nejprv Marii Magdaléně, z níž byl vyvrhl sedm ďáblů.',
        10: 'Ona pak šedši, zvěstovala těm, kteříž s ním bývali, lkajícím a plačícím.',
        11: 'A oni slyšavše, že by živ byl, a vidín od ní, nevěřili.',
        12: 'Potom pak dvěma z nich jdoucím ukázal se v jiné způsobě, když šli přes pole.',
        13: 'A ti šedše, pověděli jiným. Ani těm nevěřili.',
        14: 'Potom sedícím spolu jedenácti ukázal se, a trestal nedověru jejich a tvrdost srdce, že těm, kteříž jej viděli vzkříšeného, nevěřili.',
        15: 'A řekl jim: Jdouce po všem světě, kažte evangelium všemu stvoření.',
        16: 'Kdož uvěří a pokřtí se, spasen bude; kdož pak neuvěří, budeť zatracen.',
        17: 'Znamení pak ti, kteříž uvěří, tato míti budou: Ve jménu mém ďábly budou vymítati, jazyky novými mluviti,',
        18: 'Hady bráti, a jestliže by co jedovatého pili, nikoliť jim neuškodí; na nemocné ruce vzkládati budou, a dobře se míti budou.',
        19: 'Když pak jim odmluvil Pán, zhůru vzat jest do nebe, a sedí na pravici Boží.',
        20: 'A oni vyšedše, kázali všudy, a Pán jim pomáhal, a slov jejich potvrzoval činěním divů.',
    },
}
